corrected_code:
const express = require('express');
const { EventStoreDBClient, jsonEvent } = require('@eventstore/db-client');
const { authMiddleware } = require('../auth');

const router = express.Router();
const client = EventStoreDBClient.connectionString(process.env.EVENTSTORE_URL);

router.post('/api/commands/employees/designation', authMiddleware, async (req, res) => {
  const { employeeId, newTitle, department } = req.body;

  if (!req.user.roles?.includes('HR_MANAGER')) {
    return res.status(403).json({ error: 'Forbidden: requires HR_MANAGER role to update employee designation' });
  }

  const event = jsonEvent({
    type: 'EmployeeDesignationChanged',
    data: { employeeId, newTitle, department, changedBy: req.user.id, effectiveDate: new Date() }
  });

  await client.appendToStream(`employee-${employeeId}`, [event]);
  res.json({ status: 'dispatched', employeeId, newTitle });
});
